/*@ENGINE@*/

const PLUGIN_ID = 'gemini-live'
const ROUTE = '/gemini-live'
const STYLE_ID = 'glive-plugin-style'
const CSS = /*@CSS@*/ ''

const $call = atom(null)
const $status = atom(null)
const $models = atom([])

let engine = null
let pluginCtx = null
let voiceSessionId = ''

function idle(call) {
  return !call || call.phase === 'idle'
}

function active(call) {
  return Boolean(call) && (call.phase === 'connecting' || call.phase === 'live' || call.phase === 'reconnecting')
}

function phaseLabel(call) {
  if (!call) {
    return 'Ready'
  }

  switch (call.phase) {
    case 'connecting':
      return 'Connecting…'
    case 'reconnecting':
      return 'Reconnecting…'
    case 'error':
      return 'Call failed'
    case 'ending':
      return 'Ending…'
    case 'live':
      if (call.muted) {
        return call.pausedUntil ? 'Paused' : 'Muted'
      }
      if (call.modelSpeaking) {
        return 'Speaking'
      }
      if (call.delegation && call.delegation.approval) {
        return `${call.agentName} needs you`
      }
      if (call.delegation && call.delegation.status === 'working') {
        return `${call.agentName} is working`
      }
      return call.userSpeaking ? 'Hearing you' : 'Listening'
    default:
      return 'Ready'
  }
}

function elapsed(since) {
  const s = Math.max(0, Math.floor((Date.now() - since) / 1000))

  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`
}

function cssVar(name, fallbackVar) {
  const root = getComputedStyle(document.documentElement)

  return (root.getPropertyValue(name) || root.getPropertyValue(fallbackVar) || '').trim()
}

// ── backend doors ───────────────────────────────────────────────────────────────────────────────

async function rest(path, opts) {
  return pluginCtx.rest(path, opts ? { method: opts.method, body: opts.body } : undefined)
}

async function chatContext() {
  const sessionId = host.state.focusedSessionId.get()

  if (!sessionId) {
    return {}
  }

  const [history, live] = await Promise.all([
    host.request('session.history', { session_id: sessionId }, 15000).catch(() => null),
    host.request('session.active_list', { current_session_id: sessionId }, 10000).catch(() => null)
  ])
  const row = ((live && live.sessions) || []).find(s => s.id === sessionId)
  const recent = glCondense((history && history.messages) || [], 12).filter(m => m.role !== 'tool')

  return { chat_title: (row && row.title) || '', recent }
}

function getEngine() {
  if (engine) {
    return engine
  }

  engine = createGeminiLiveEngine({
    rest,
    rpc: (method, params, timeoutMs) => host.request(method, params || {}, timeoutMs),
    onEvent: listener => pluginCtx.onEvent('*', listener),
    focus: () => ({ sessionId: host.state.focusedSessionId.get(), storedId: host.state.focusedStoredSessionId.get() }),
    submitToChat: (sessionId, text) => host.composer.submit(sessionId, text),
    // A call started with no chat open still needs somewhere for the work to run.
    ensureSession: async () => {
      if (!voiceSessionId) {
        const created = await host.request('session.create', {}, 30000)
        voiceSessionId = (created && created.session_id) || ''
      }

      return voiceSessionId
    },
    chatContext,
    log: (level, message) => {
      if (level !== 'debug') {
        console.info(`[gemini-live] ${message}`)
      }
    }
  })
  engine.subscribe(snapshot => $call.set(snapshot))

  return engine
}

async function refreshStatus() {
  try {
    $status.set(await rest('/status'))
  } catch (error) {
    $status.set({ ok: false, error: (error && error.message) || String(error) })
  }

  return $status.get()
}

async function refreshModels() {
  try {
    const response = await rest('/models')
    $models.set((response && response.models) || [])
  } catch {
    $models.set([])
  }
}

async function startCall(options) {
  haptic('open')
  const status = $status.get() || (await refreshStatus())

  if (status && status.ok && !status.configured) {
    host.notify({
      kind: 'warning',
      title: 'Gemini Live needs a key',
      message: 'Add your Gemini API key in Settings → Plugins → Gemini Live.'
    })
    host.navigate(`/settings?tab=plugins&agent=${PLUGIN_ID}`)

    return
  }

  await getEngine().start(options || {})
  const call = $call.get()

  if (call && call.phase === 'error') {
    host.notify({ kind: 'error', title: 'Gemini Live', message: call.error })
  }
}

function endCall() {
  haptic('close')
  void getEngine().stop()
}

// ── visuals ─────────────────────────────────────────────────────────────────────────────────────

function Orb({ size }) {
  const ref = useRef(null)
  const call = useValue($call)
  const phaseRef = useRef('idle')
  phaseRef.current = call ? call.phase : 'idle'

  useEffect(() => {
    const canvas = ref.current
    if (!canvas) {
      return undefined
    }

    const dpr = window.devicePixelRatio || 1
    canvas.width = size * dpr
    canvas.height = size * dpr
    const g = canvas.getContext('2d')
    const accent = cssVar('--ui-accent', '--ui-blue') || 'currentColor'
    const reduced = Boolean(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches)
    const orb = glCreateOrb()
    let raf = 0

    const frame = now => {
      const lv = engine ? engine.levels() : { input: 0, output: 0 }
      const v = engine ? engine.visual() : { working: false, tools: 0 }
      orb.draw(g, canvas.width, { ...lv, ...v, phase: phaseRef.current, color: accent, reduced, now })
      raf = window.requestAnimationFrame(frame)
    }

    raf = window.requestAnimationFrame(frame)

    return () => window.cancelAnimationFrame(raf)
  }, [size])

  return jsx('canvas', { className: 'glive-orb', ref, style: { height: `${size}px`, width: `${size}px` } })
}

function Ticker({ since }) {
  const [, force] = useState(0)

  useEffect(() => {
    const id = window.setInterval(() => force(n => n + 1), 1000)

    return () => window.clearInterval(id)
  }, [])

  return jsx('span', { className: 'glive-mono', children: elapsed(since) })
}

function IconButton({ icon, label, onClick, tone, disabled }) {
  return jsx(Tip, {
    label,
    children: jsx(Button, {
      'aria-label': label,
      className: tone ? `glive-icon glive-icon--${tone}` : 'glive-icon',
      disabled,
      onClick,
      size: 'icon-xs',
      type: 'button',
      variant: 'ghost',
      children: jsx(Codicon, { name: icon, size: '0.875rem' })
    })
  })
}

function latestCaption(call) {
  for (let i = call.transcript.length - 1; i >= 0; i -= 1) {
    const t = call.transcript[i]
    if (t.role === 'assistant' || t.role === 'user') {
      return { role: t.role, text: glSquash(t.text).slice(-160) }
    }
  }

  return null
}

