function Threads({ visible }) {
  const [rows, setRows] = useState(null)
  const [error, setError] = useState('')

  useEffect(() => {
    if (!visible) {
      return undefined
    }

    let stop = false
    const load = async () => {
      try {
        const [live, roster] = await Promise.all([
          host.request('session.active_list', { current_session_id: host.state.focusedSessionId.get() || null }, 10000),
          host.request('profiles.list', { include_sessions: true }, 15000).catch(() => null)
        ])
        const threads = ((live && live.sessions) || []).map(s => ({ id: s.id, storedId: s.session_key || s.id, title: s.title || 'Untitled', status: s.status, preview: s.preview, current: s.current, bot: '' }))
        const bots = ((roster && roster.profiles) || [])
          .filter(p => !p.is_default && p.canonical_session)
          .map(p => ({ id: `bot:${p.name}`, storedId: p.canonical_session.resolved_id || p.canonical_session.id, title: p.display_name || p.name, status: 'bot', preview: p.canonical_session.preview, bot: p.name }))
        if (!stop) {
          setRows([...threads, ...bots])
          setError('')
        }
      } catch (err) {
        if (!stop) {
          setError((err && err.message) || String(err))
        }
      }
    }

    void load()
    const id = window.setInterval(load, 5000)

    return () => {
      stop = true
      window.clearInterval(id)
    }
  }, [visible])

  const open = row => {
    const options = row.bot ? { awaitHydration: true, forceResume: true, profile: row.bot } : {}
    Promise.resolve(host.openSession(row.storedId, options)).catch(err => setError((err && err.message) || String(err)))
  }

  if (error) {
    return jsx('div', { className: 'glive-empty', children: error })
  }

  if (!rows) {
    return jsx('div', { className: 'glive-empty', children: 'Loading threads…' })
  }

  if (!rows.length) {
    return jsx('div', { className: 'glive-empty', children: 'No threads are running.' })
  }

  return jsx('div', {
    className: 'glive-scroll',
    children: rows.map(r =>
      jsxs(
        'div',
        {
          className: 'glive-thread glive-thread--open',
          onClick: () => open(r),
          onKeyDown: event => {
            if (event.key === 'Enter') {
              open(r)
            }
          },
          role: 'button',
          tabIndex: 0,
          children: [
            jsx('span', { className: `glive-dot glive-dot--${GL_BUSY_STATUSES[r.status] ? 'busy' : r.status === 'bot' ? 'bot' : 'idle'}` }),
            jsxs('div', {
              className: 'glive-thread__body',
              children: [
                jsxs('div', {
                  className: 'glive-thread__title',
                  children: [
                    jsx('span', { className: 'glive-strong glive-ellipsis', children: r.title }),
                    jsx('span', { className: 'glive-dim', children: r.bot ? 'bot chat' : r.current ? `${r.status} · on screen` : r.status })
                  ]
                }),
                r.preview ? jsx('div', { className: 'glive-dim glive-ellipsis', children: r.preview }) : null
              ]
            })
          ]
        },
        r.id
      )
    )
  })
}

function ConsolePage() {
  const call = useValue($call)
  const status = useValue($status)
  const models = useValue($models)
  const [tab, setTab] = useState('transcript')
  const [text, setText] = useState('')
  const [choice, setChoice] = useState({ model: '', voice: '', persona: '' })

  useEffect(() => {
    void refreshStatus().then(s => {
      if (s && s.configured) {
        void refreshModels()
      }
    })
  }, [])

  const live = active(call)
  const settings = (status && status.settings) || {}
  const model = choice.model || (call && call.model) || settings.model || 'gemini-3.8-live'
  const voice = choice.voice || (call && call.voice) || settings.voice || 'Laomedeia'
  const persona = choice.persona || (call && call.persona) || settings.persona || 'hermes'
  const modelOptions = models.length ? models.map(m => ({ id: m.id, label: m.label })) : [{ id: model, label: model }]
  if (!modelOptions.some(o => o.id === model)) {
    modelOptions.unshift({ id: model, label: model })
  }
  const voiceOptions = ((status && status.voices) || [voice]).map(v => ({ id: v, label: v }))
  const personaOptions = ((status && status.personas) || [{ id: persona, label: persona }]).map(p => ({ id: p.id, label: p.label }))
  const notConfigured = status && status.ok && !status.configured

  return jsxs('div', {
    className: 'glive-page',
    children: [
      jsxs('section', {
        className: 'glive-stage',
        children: [
          jsx(Orb, { size: 208 }),
          jsx('div', { className: 'glive-stage__phase', children: phaseLabel(call) }),
          jsx('div', {
            className: 'glive-dim',
            children: live ? jsxs('span', { children: [`${call.model} · ${call.voice} · ${call.personaLabel} · `, jsx(Ticker, { since: call.startedAt })] }) : 'Full-duplex voice with your Hermes agent'
          }),
          call && call.phase === 'error' ? jsx('div', { className: 'glive-error', children: call.error }) : null,
          notConfigured
            ? jsxs('div', {
                className: 'glive-setup',
                children: [
                  jsx('div', { className: 'glive-strong', children: 'Add your Gemini API key to start' }),
                  jsx('div', { className: 'glive-dim', children: 'Get one free at aistudio.google.com/apikey, then paste it into the plugin settings.' }),
                  jsx(Button, { onClick: () => host.navigate(`/settings?tab=plugins&agent=${PLUGIN_ID}`), size: 'sm', type: 'button', variant: 'default', children: 'Open settings' })
                ]
              })
            : null,
          jsxs('div', {
            className: 'glive-controls',
            children: live
              ? [
                  jsx(Button, { onClick: () => getEngine().toggleMute(), size: 'sm', type: 'button', variant: 'secondary', children: call.muted ? 'Unmute' : 'Mute' }, 'mute'),
                  jsx(Button, { onClick: endCall, size: 'sm', type: 'button', variant: 'destructive', children: 'End call' }, 'end')
                ]
              : [
                  jsx(
                    Button,
                    {
                      disabled: Boolean(notConfigured),
                      onClick: () => void startCall({ model, voice, persona }),
                      size: 'lg',
                      type: 'button',
                      variant: 'default',
                      children: 'Start call'
                    },
                    'start'
                  )
                ]
          }),
          jsxs('div', {
            className: 'glive-pickers',
            children: [
              jsx(Picker, { disabled: live, label: 'Model', onChange: v => setChoice(c => ({ ...c, model: v })), options: modelOptions, value: model }),
              jsx(Picker, {
                label: 'Voice',
                onChange: v => {
                  setChoice(c => ({ ...c, voice: v }))
                  if (live) {
                    getEngine().switchVoice(v)
                  }
                },
                options: voiceOptions,
                value: voice
              }),
              jsx(Picker, {
                label: 'Persona',
                onChange: v => {
                  setChoice(c => ({ ...c, persona: v }))
                  if (live) {
                    getEngine().switchPersona(v)
                  }
                },
                options: personaOptions,
                value: persona
              })
            ]
          }),
          live
            ? jsx('form', {
                className: 'glive-type',
                onSubmit: event => {
                  event.preventDefault()
                  if (getEngine().sendText(text)) {
                    setText('')
                  }
                },
                children: jsx('input', {
                  className: 'glive-input',
                  onChange: event => setText(event.target.value),
                  placeholder: 'Or type to the voice…',
                  value: text
                })
              })
            : null,
          status && status.memory_provider ? jsx('div', { className: 'glive-dim glive-small', children: `Memory: ${status.memory_provider}` }) : null
        ]
      }),
      jsxs('section', {
        className: 'glive-side',
        children: [
          jsx('div', {
            className: 'glive-tabs',
            children: [
              ['transcript', 'Transcript'],
              ['activity', 'Activity'],
              ['threads', 'Threads']
            ].map(([id, label]) =>
              jsx('button', { className: tab === id ? 'glive-tab glive-tab--on' : 'glive-tab', onClick: () => setTab(id), type: 'button', children: label }, id)
            )
          }),
          tab === 'transcript' ? jsx(Transcript, { call }) : null,
          tab === 'activity' ? jsx(Activity, { call }) : null,
          jsx('div', { style: { display: tab === 'threads' ? 'contents' : 'none' }, children: jsx(Threads, { visible: tab === 'threads' }) })
        ]
      })
    ]
  })
}

// ── registration ────────────────────────────────────────────────────────────────────────────────

export default {
  id: PLUGIN_ID,
  name: 'Gemini Live',
  register(ctx) {
    pluginCtx = ctx

    if (!document.getElementById(STYLE_ID)) {
      const style = document.createElement('style')
      style.id = STYLE_ID
      style.textContent = CSS
      document.head.appendChild(style)
    }

    ctx.onDispose(() => {
      if (engine) {
        void engine.stop()
        engine = null
      }
      const style = document.getElementById(STYLE_ID)
      if (style) {
        style.remove()
      }
    })

    ctx.onEvent('plugin.gemini-live.settings.changed', () => void refreshStatus())
    void refreshStatus()

    // Hosts with the voice-engine picker area list "Gemini Live" next to the built-in engines and
    // route the start-voice button to it; older hosts get the plugin's own composer button.
    const engineArea = COMPOSER_AREAS.voiceEngines
    const entry = engineArea
      ? {
          id: 'engine',
          area: engineArea,
          data: {
            label: 'Gemini Live (full-duplex, delegates to Hermes)',
            shortLabel: 'Gemini Live',
            detail: 'Your Gemini API key · pick the model on the call screen',
            start: () => void startCall()
          }
        }
      : { id: 'composer-button', area: COMPOSER_AREAS.actions, order: 40, render: () => jsx(ComposerButton, {}) }

    ctx.registerMany([
      entry,
      { id: 'call-bar', area: COMPOSER_AREAS.top, order: 10, render: () => jsx(CallBar, {}) },
      { id: 'status', area: STATUSBAR_AREAS.right, order: 115, render: () => jsx(StatusChip, {}) },
      { id: 'page', area: ROUTES_AREA, data: { path: ROUTE }, render: () => jsx(ConsolePage, {}) },
      { id: 'nav', area: SIDEBAR_NAV_AREA, data: { path: ROUTE, label: 'Gemini Live', codicon: 'broadcast' } },
      {
        id: 'cmd-start',
        area: PALETTE_AREA,
        data: { id: 'gemini-live.start', label: 'Gemini Live: Start voice call', keywords: ['voice', 'call', 'gemini', 'live', 'talk'], run: () => void startCall() }
      },
      { id: 'cmd-end', area: PALETTE_AREA, data: { id: 'gemini-live.end', label: 'Gemini Live: End call', keywords: ['voice', 'hang up'], run: endCall } },
      { id: 'cmd-mute', area: PALETTE_AREA, data: { id: 'gemini-live.mute', label: 'Gemini Live: Toggle mute', keywords: ['voice', 'mute'], run: () => getEngine().toggleMute() } },
      { id: 'cmd-open', area: PALETTE_AREA, data: { id: 'gemini-live.open', label: 'Gemini Live: Open console', keywords: ['voice'], run: () => host.navigate(ROUTE) } }
    ])
  }
}
